using System;

public class Solution {
    public string AbbreviateProduct(int left, int right) {
        int c2 = 0, c5 = 0;
        for (int i = left; i <= right; i++) {
            int x = i;
            while ((x & 1) == 0) { c2++; x >>= 1; }
            while (x % 5 == 0) { c5++; x /= 5; }
        }
        int c = Math.Min(c2, c5);

        int rem2 = c, rem5 = c;
        long prod = 1;
        bool over = false;
        const long limit = 10000000000L; // 10^10

        for (int i = left; i <= right; i++) {
            int x = i;
            while (rem2 > 0 && (x & 1) == 0) {
                x >>= 1;
                rem2--;
            }
            while (rem5 > 0 && x % 5 == 0) {
                x /= 5;
                rem5--;
            }

            prod *= x;
            if (prod >= limit) {
                over = true;
                prod %= limit;
            }
        }

        if (!over) {
            return $"{prod}e{c}";
        }

        double logSum = 0;
        for (int i = left; i <= right; i++) {
            logSum += Math.Log10(i);
        }
        logSum -= c;
        double q = logSum - Math.Floor(logSum);
        int first5 = (int)(Math.Pow(10, q) * 10000);
        if (first5 >= 100000) {
            first5 /= 10;
        }

        long last5 = prod % 100000;
        return $"{first5}...{last5:D5}e{c}";
    }
}
