using System;
using System.Collections.Generic;

public class Solution {
    private class IndexComparer : IComparer<int> {
        private readonly int[] _nums;
        public IndexComparer(int[] nums) {
            _nums = nums;
        }

        public int Compare(int a, int b) {
            int cmp = _nums[a].CompareTo(_nums[b]);
            if (cmp != 0) return cmp;
            return a.CompareTo(b);
        }
    }

    public double[] MedianSlidingWindow(int[] nums, int k) {
        int n = nums.Length;
        double[] result = new double[n - k + 1];
        var comparer = new IndexComparer(nums);
        var left = new SortedSet<int>(comparer);
        var right = new SortedSet<int>(comparer);

        void Balance() {
            int targetLeft = (k + 1) / 2;
            while (left.Count > targetLeft) {
                int val = left.Max;
                left.Remove(val);
                right.Add(val);
            }
            while (left.Count < targetLeft) {
                int val = right.Min;
                right.Remove(val);
                left.Add(val);
            }
        }

        void Add(int index) {
            if (left.Count == 0 || nums[index] <= nums[left.Max]) {
                left.Add(index);
            } else {
                right.Add(index);
            }
            Balance();
        }

        void Remove(int index) {
            if (left.Contains(index)) {
                left.Remove(index);
            } else {
                right.Remove(index);
            }
            Balance();
        }

        for (int i = 0; i < k; i++) {
            Add(i);
        }

        result[0] = (k % 2 == 1) 
            ? nums[left.Max] 
            : ((double)nums[left.Max] + nums[right.Min]) / 2.0;

        for (int i = k; i < n; i++) {
            Add(i);
            Remove(i - k);

            result[i - k + 1] = (k % 2 == 1) 
                ? nums[left.Max] 
                : ((double)nums[left.Max] + nums[right.Min]) / 2.0;
        }

        return result;
    }
}
