public class Solution {
    public IList<string> AmbiguousCoordinates(string s) {
        var result = new List<string>();
        string inner = s.Substring(1, s.Length - 2);

        for (int i = 1; i < inner.Length; i++) {
            string left = inner.Substring(0, i);
            string right = inner.Substring(i);

            var leftVals = GetValid(left);
            var rightVals = GetValid(right);

            foreach (var l in leftVals) {
                foreach (var r in rightVals) {
                    result.Add($"({l}, {r})");
                }
            }
        }

        return result;
    }

    private List<string> GetValid(string t) {
        var list = new List<string>();
        int n = t.Length;

        for (int i = 1; i <= n; i++) {
            if (i == n) {
                if (n == 1 || t[0] != '0') {
                    list.Add(t);
                }
            } else {
                string intPart = t.Substring(0, i);
                string fracPart = t.Substring(i);

                if ((intPart.Length == 1 || intPart[0] != '0') && fracPart[fracPart.Length - 1] != '0') {
                    list.Add(intPart + "." + fracPart);
                }
            }
        }

        return list;
    }
}
