An elegant and optimal way to solve this problem is to **reverse the process**. 

Instead of removing bricks and finding out which bricks become disconnected (which is difficult in a dynamic graph), we can:
1. Apply all the hits initially to find the final state of the grid.
2. Build a Disjoint Set Union (DSU) / Union-Find data structure with the remaining bricks, connecting bricks adjacent to each other and connecting all bricks in row `0` to a virtual "roof" node.
3. Process the hits in reverse order (from last to first):
   - Add the brick back into the grid.
   - Connect it to its adjacent bricks (and to the roof if it is on row `0`).
   - If this addition connects a new component to the roof, the number of bricks that would have fallen during the forward hit is `(new_roof_size - old_roof_size - 1)`. The `-1` accounts for the brick being hit itself.

### C# Solution

```csharp
public class Solution {
    public int[] HitBricks(int[][] grid, int[][] hits) {
        int m = grid.Length;
        int n = grid[0].Length;

        // Copy grid state after all hits
        // If grid[r][c] was 1, decrementing makes it 0.
        // If grid[r][c] was 0, decrementing makes it -1.
        int[][] state = new int[m][];
        for (int i = 0; i < m; i++) {
            state[i] = (int[])grid[i].Clone();
        }
        foreach (var hit in hits) {
            state[hit[0]][hit[1]]--;
        }

        int top = m * n; // Virtual node representing the roof
        UnionFind uf = new UnionFind(top + 1);
        uf.Size[top] = 0; // The virtual roof itself does not count as a brick

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        // Build initial DSU with the remaining bricks (where state[r][c] == 1)
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (state[r][c] == 1) {
                    int index = r * n + c;
                    if (r == 0) {
                        uf.Union(index, top);
                    }
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && state[nr][nc] == 1) {
                            uf.Union(index, nr * n + nc);
                        }
                    }
                }
            }
        }

        int[] result = new int[hits.Length];

        // Process hits in reverse
        for (int i = hits.Length - 1; i >= 0; i--) {
            int r = hits[i][0];
            int c = hits[i][1];

            state[r][c]++;
            // If it became 1, it was originally a brick
            if (state[r][c] == 1) {
                int prevRoofSize = uf.GetSize(top);
                int index = r * n + c;

                if (r == 0) {
                    uf.Union(index, top);
                }

                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && state[nr][nc] == 1) {
                        uf.Union(index, nr * n + nc);
                    }
                }

                int currRoofSize = uf.GetSize(top);
                // If the roof component size grew, bricks were restored
                // The hit brick itself is not counted as fallen, so subtract 1
                result[i] = Math.Max(0, currRoofSize - prevRoofSize - 1);
            }
        }

        return result;
    }

    private class UnionFind {
        private int[] parent;
        public int[] Size;

        public UnionFind(int n) {
            parent = new int[n];
            Size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                Size[i] = 1;
            }
        }

        public int Find(int i) {
            if (parent[i] != i) {
                parent[i] = Find(parent[i]);
            }
            return parent[i];
        }

        public void Union(int i, int j) {
            int rootI = Find(i);
            int rootJ = Find(j);
            if (rootI != rootJ) {
                parent[rootI] = rootJ;
                Size[rootJ] += Size[rootI];
            }
        }

        public int GetSize(int i) {
            return Size[Find(i)];
        }
    }
}
