public class Solution {
    public int Clumsy(int n) {
        int ans = 0;

        // First group (positive)
        int term = n--;
        if (n > 0) { term *= n--; }
        if (n > 0) { term /= n--; }
        ans += term;
        if (n > 0) { ans += n--; }

        // Subsequent groups (subtracted)
        while (n > 0) {
            term = n--;
            if (n > 0) { term *= n--; }
            if (n > 0) { term /= n--; }
            ans -= term;
            if (n > 0) { ans += n--; }
        }

        return ans;
    }
}
