public class Solution {
    public int CountVowelSubstrings(string word) {
        int n = word.Length;
        int count = 0;

        for (int i = 0; i < n; i++) {
            int mask = 0;
            for (int j = i; j < n; j++) {
                char c = word[j];
                if (c == 'a') mask |= 1;
                else if (c == 'e') mask |= 2;
                else if (c == 'i') mask |= 4;
                else if (c == 'o') mask |= 8;
                else if (c == 'u') mask |= 16;
                else break;

                if (mask == 31) {
                    count++;
                }
            }
        }

        return count;
    }
