public class Solution {
    public int MaxPoints(int[][] points) {
        int n = points.Length;
        if (n <= 2) return n;

        int maxPoints = 0;

        for (int i = 0; i < n; i++) {
            var slopeCounts = new Dictionary<(int, int), int>();
            int currentMax = 0;

            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];

                int g = Gcd(Math.Abs(dx), Math.Abs(dy));
                dx /= g;
                dy /= g;

                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }

                var key = (dx, dy);
                slopeCounts[key] = slopeCounts.GetValueOrDefault(key, 0) + 1;
                currentMax = Math.Max(currentMax, slopeCounts[key]);
            }

            maxPoints = Math.Max(maxPoints, currentMax + 1);
        }

        return maxPoints;
    }

    private int Gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
