public class Solution {
    public long MaxRunTime(int n, int[] batteries) {
        long sum = 0;
        foreach (int b in batteries) {
            sum += b;
        }

        long low = 1;
        long high = sum / n;
        long ans = 0;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            long total = 0;
            foreach (int b in batteries) {
                total += System.Math.Min((long)b, mid);
            }

            if (total >= mid * n) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return ans;
    }
