using System;
using System.Numerics;

public class Solution {
    public int MaxStudents(char[][] seats) {
        int m = seats.Length;
        int n = seats[0].Length;

        int[] validSeats = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') {
                    mask |= (1 << j);
                }
            }
            validSeats[i] = mask;
        }

        int numMasks = 1 << n;
        int[] dp = new int[numMasks];
        Array.Fill(dp, -1);
        dp[0] = 0;

        for (int i = 0; i < m; i++) {
            int[] nextDp = new int[numMasks];
            Array.Fill(nextDp, -1);

            for (int curr = 0; curr < numMasks; curr++) {
                if ((curr & (curr >> 1)) != 0) continue;
                if ((curr & ~validSeats[i]) != 0) continue;

                int count = BitOperations.PopCount((uint)curr);

                for (int prev = 0; prev < numMasks; prev++) {
                    if (dp[prev] == -1) continue;
                    if ((curr & (prev >> 1)) != 0) continue;
                    if ((curr & (prev << 1)) != 0) continue;

                    if (dp[prev] + count > nextDp[curr]) {
                        nextDp[curr] = dp[prev] + count;
                    }
                }
            }

            dp = nextDp;
        }

        int maxStudents = 0;
        for (int mask = 0; mask < numMasks; mask++) {
            if (dp[mask] > maxStudents) {
                maxStudents = dp[mask];
            }
        }

        return maxStudents;
    }
}
