    private int Count(int[] a, int[] b) {
        var productCount = new Dictionary<long, int>();
        for (int j = 0; j < b.Length; j++) {
            for (int k = j + 1; k < b.Length; k++) {
                long prod = (long)b[j] * b[k];
                if (productCount.TryGetValue(prod, out int count)) {
