using System;

public class Solution {
    public int MaxSizeSlices(int[] slices) {
        int n = slices.Length / 3;
        int case1 = MaxLinear(slices, 0, slices.Length - 2, n);
        int case2 = MaxLinear(slices, 1, slices.Length - 1, n);
        return Math.Max(case1, case2);
    }

    private int MaxLinear(int[] slices, int start, int end, int k) {
        int m = end - start + 1;
        int[,] dp = new int[m + 1, k + 1];

        for (int i = 1; i <= m; i++) {
            int val = slices[start + i - 1];
            for (int j = 1; j <= k; j++) {
                int take = (i >= 2 ? dp[i - 2, j - 1] : 0) + val;
                int notTake = dp[i - 1, j];
                dp[i, j] = Math.Max(notTake, take);
            }
        }

        return dp[m, k];
    }
}
