public class Solution {
    public bool[] FriendRequests(int n, int[][] restrictions, int[][] requests) {
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        int Find(int i) {
            if (parent[i] == i) return i;
            return parent[i] = Find(parent[i]);
        }

        bool[] ans = new bool[requests.Length];

        for (int i = 0; i < requests.Length; i++) {
            int rootU = Find(requests[i][0]);
            int rootV = Find(requests[i][1]);

            if (rootU == rootV) {
                ans[i] = true;
                continue;
            }

            bool canUnion = true;
            foreach (var r in restrictions) {
                int rx = Find(r[0]);
                int ry = Find(r[1]);

                if ((rx == rootU && ry == rootV) || (rx == rootV && ry == rootU)) {
                    canUnion = false;
                    break;
                }
            }

            if (canUnion) {
                parent[rootU] = rootV;
                ans[i] = true;
            } else {
                ans[i] = false;
            }
        }

        return ans;
    }
}
