```csharp
using System;

public class Solution {
    private int[,,] memoEarliest = new int[30, 30, 30];
    private int[,,] memoLatest = new int[30, 30, 30];

    public int[] EarliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        var res = Dfs(n, firstPlayer, secondPlayer);
        return new int[] { res.minRound, res.maxRound };
    }

    private (int minRound, int maxRound) Dfs(int n, int p1, int p2) {
        if (p1 + p2 == n + 1) {
            return (1, 1);
        }

        if (p1 + p2 > n + 1) {
            return Dfs(n, n + 1 - p2, n + 1 - p1);
        }

        if (memoEarliest[n, p1, p2] != 0) {
            return (memoEarliest[n, p1, p2], memoLatest[n, p1, p2]);
        }

        int minRound = int.MaxValue;
        int maxRound = int.MinValue;
        int nextN = (n + 1) / 2;

        if (p2 <= (n + 1) / 2) {
            int maxK1 = p1 - 1;
            int maxK2 = p2 - p1 - 1;

            for (int k1 = 0; k1 <= maxK1; k1++) {
                for (int k2 = 0; k2 <= maxK2; k2++) {
                    int nextP1 = 1 + k1;
                    int nextP2 = 2 + k1 + k2;
                    var sub = Dfs(nextN, nextP1, nextP2);
                    minRound = Math.Min(minRound, 1 + sub.minRound);
                    maxRound = Math.Max(maxRound, 1 + sub.maxRound);
                }
            }
        } else {
            int p2Prime = n + 1 - p2;
            int maxK1 = p1 - 1;
            int maxK2 = p2Prime - p1 - 1;
            int offset = (n + 1) / 2 - p2Prime;

            for (int k1 = 0; k1 <= maxK1; k1++) {
                for (int k2 = 0; k2 <= maxK2; k2++) {
                    int nextP1 = 1 + k1;
                    int nextP2 = 2 + k1 + k2 + offset;
                    var sub = Dfs(nextN, nextP1, nextP2);
                    minRound = Math.Min(minRound, 1 + sub.minRound);
                    maxRound = Math.Max(maxRound, 1 + sub.maxRound);
                }
            }
        }

        memoEarliest[n, p1, p2] = minRound;
        memoLatest[n, p1, p2] = maxRound;
        return (minRound, maxRound);
    }
}
