public class Solution {
    public int[] KWeakestRows(int[][] mat, int k) {
        int m = mat.Length;
        int n = mat[0].Length;

        return Enumerable.Range(0, m)
            .Select(i => {
                int count = 0;
                while (count < n && mat[i][count] == 1) {
                    count++;
                }
                return (Count: count, Index: i);
            })
            .OrderBy(x => x.Count)
            .ThenBy(x => x.Index)
            .Take(k)
            .Select(x => x.Index)
            .ToArray();
    }
}
