An elegant and optimal way to solve this problem is using **column-by-column backtracking** (from the least significant digit / rightmost column to the most significant digit). 

This approach is significantly faster than standard brute force or letter-by-letter assignment because it prunes invalid digit assignments as early as possible using the modulo 10 arithmetic constraint at each column.

### C# Source Code

```csharp
using System;

public class Solution {
    private int[] charToDigit;
    private bool[] digitUsed;
    private bool[] cannotBeZero;
    private string[] words;
    private string result;
    private int maxLen;

    public bool IsSolvable(string[] words, string result) {
        this.words = words;
        this.result = result;

        this.charToDigit = new int[26];
        Array.Fill(this.charToDigit, -1);
        this.digitUsed = new bool[10];
        this.cannotBeZero = new bool[26];

        int maxWordLen = 0;
        foreach (var word in words) {
            maxWordLen = Math.Max(maxWordLen, word.Length);
            if (word.Length > 1) {
                cannotBeZero[word[0] - 'A'] = true;
            }
        }

        if (result.Length > 1) {
            cannotBeZero[result[0] - 'A'] = true;
        }

        // The result cannot have fewer digits than the longest word,
        // and cannot exceed the longest word's length by more than 1.
        if (result.Length < maxWordLen || result.Length > maxWordLen + 1) {
            return false;
        }

        this.maxLen = result.Length;

        return Backtrack(0, 0, 0);
    }

    private bool Backtrack(int col, int wordIdx, int carry) {
        // If we processed all columns, the equation holds if there is no remaining carry.
        if (col == maxLen) {
            return carry == 0;
        }

        // If we are still summing the words in the current column
        if (wordIdx < words.Length) {
            string word = words[wordIdx];
            if (col >= word.Length) {
                return Backtrack(col, wordIdx + 1, carry);
            }

            char c = word[word.Length - 1 - col];
            int cIdx = c - 'A';

            if (charToDigit[cIdx] != -1) {
                return Backtrack(col, wordIdx + 1, carry + charToDigit[cIdx]);
            } else {
                for (int d = 0; d <= 9; d++) {
                    if (d == 0 && cannotBeZero[cIdx]) continue;
                    if (digitUsed[d]) continue;

                    charToDigit[cIdx] = d;
                    digitUsed[d] = true;

                    if (Backtrack(col, wordIdx + 1, carry + d)) {
                        return true;
                    }

                    digitUsed[d] = false;
                    charToDigit[cIdx] = -1;
                }
                return false;
            }
        }

        // We finished summing all words for the current column; now match with the result
        char resChar = result[result.Length - 1 - col];
        int resCharIdx = resChar - 'A';
        int target = carry % 10;
        int nextCarry = carry / 10;

        if (charToDigit[resCharIdx] != -1) {
            if (charToDigit[resCharIdx] == target) {
                return Backtrack(col + 1, 0, nextCarry);
            }
            return false;
        } else {
            if (target == 0 && cannotBeZero[resCharIdx]) return false;
            if (digitUsed[target]) return false;

            charToDigit[resCharIdx] = target;
            digitUsed[target] = true;

            if (Backtrack(col + 1, 0, nextCarry)) {
                return true;
            }

            digitUsed[target] = false;
            charToDigit[resCharIdx] = -1;
            return false;
        }
    }
}
